/**
 * The painted chest and the ground it stands on, for the opening only (lazy with
 * ChestOpening, so none of this is in the #/app cold load).
 *
 * The strings come from chestPaint.ts, generated by scripts/gen-chest-model.mjs from
 * a small 3-D model under one light. They are our own static markup, never student
 * or network text. They are set once and never re-rendered: the lid is the attribute
 * `data-lid` on the svg, moved by ChestOpening without React, one frame at a time.
 */
import { memo } from "react";
import { CHEST_LAYERS, CHEST_VIEW } from "./chestPaint";
import "./chestPaint.css";

const VIEW_BOX = `${CHEST_VIEW.x} ${CHEST_VIEW.y} ${CHEST_VIEW.w} ${CHEST_VIEW.h}`;

/** The frame numbers of the lid: closed, cracked, then the swing to thrown back and its rest. */
export const LID_CLOSED = 0;
export const LID_CRACKED = 1;
export const LID_SWING: readonly number[] = [2, 3, 4, 5];
export const LID_OPEN = 5;

const html = (markup: string) => ({ __html: markup });

/** `drained` is the gold that stays in the box once the coins have gone. */
export const ChestModel = memo(function ChestModel({ lid, drained }: { readonly lid: number; readonly drained: boolean }) {
  return (
    <svg viewBox={VIEW_BOX} className="chest-model" data-lid={lid} aria-hidden>
      <defs dangerouslySetInnerHTML={html(CHEST_LAYERS.defs)} />
      <g dangerouslySetInnerHTML={html(CHEST_LAYERS.lidBack)} />
      <g dangerouslySetInnerHTML={html(CHEST_LAYERS.inside)} />
      <g dangerouslySetInnerHTML={html(CHEST_LAYERS.rimBack)} />
      <g dangerouslySetInnerHTML={html(drained ? CHEST_LAYERS.low : CHEST_LAYERS.full)} />
      <g dangerouslySetInnerHTML={html(CHEST_LAYERS.mouthGlow)} />
      <g dangerouslySetInnerHTML={html(CHEST_LAYERS.rimFront)} />
      <g dangerouslySetInnerHTML={html(CHEST_LAYERS.box)} />
      <g dangerouslySetInnerHTML={html(CHEST_LAYERS.plate)} />
      <g dangerouslySetInnerHTML={html(CHEST_LAYERS.lidFront)} />
    </svg>
  );
});

/**
 * What lies on the ground under the chest: the shadow it casts, tufts and pebbles.
 * It shares the chest's view box, so the shadow meets the feet at any size, and it
 * stays out of the box that squashes: the ground does not squash.
 */
export const ChestFloor = memo(function ChestFloor() {
  return (
    <svg viewBox={VIEW_BOX} className="chest-floor" aria-hidden>
      <g dangerouslySetInnerHTML={html(CHEST_LAYERS.floor)} />
      <path d={CHEST_LAYERS.castFar} className="chest-floor__cast" />
      <path d={CHEST_LAYERS.cast} className="chest-floor__cast" />
    </svg>
  );
});

/** The world: the sky, far hills and a ground plane that recedes to them. No state, no motion. */
export const ChestWorld = memo(function ChestWorld() {
  return (
    <span className="chest-world" aria-hidden>
      <svg className="chest-world__hills" viewBox="0 0 1000 200" preserveAspectRatio="none">
        <path className="chest-world__hill-far" d="M0 200V110C120 60 230 54 360 92C470 124 560 60 690 52C820 44 910 86 1000 70V200Z" />
        <path className="chest-world__hill-near" d="M0 200V150C150 112 300 118 470 150C640 182 820 118 1000 132V200Z" />
      </svg>
      <span className="chest-world__ground">
        <span className="chest-world__plane" />
        <span className="chest-world__vignette" />
      </span>
    </span>
  );
});
